      'bar.account': 'Your account',
      'bar.lang': 'Language',
      'bar.score': '<b>{points}</b> pts &nbsp; <b>{streak}</b> day streak',

      'steps.count': '{done} of {total} steps',
      'steps.count1': '{done} of {total} steps',
      'stat.points': 'Points',
      'stat.streak': 'Day streak',
      'stat.step': 'This step',
      'stat.total': 'Total',

      'home.title': 'Your courses',
      'home.acct': 'Carry your progress between devices',
